-- Expects public.products.id BIGINT and columns name, sku, quantity, price.
-- Existing product rows are preserved; products.price is interpreted as USD.
alter table public.products add column if not exists image_url text;
alter table public.products add column if not exists cost_price numeric(12,2) not null default 0;
create table if not exists public.sales(id bigint generated by default as identity primary key,invoice_no text unique not null,customer_name text,customer_phone text,subtotal_usd numeric(12,2) not null,discount_usd numeric(12,2) not null default 0,total_usd numeric(12,2) not null,payment_currency text not null check(payment_currency in('USD','KHR')),paid_amount numeric(14,2) not null,paid_usd numeric(12,2) not null,change_amount numeric(14,2) not null default 0,exchange_rate numeric(14,2) not null,cost_total_usd numeric(12,2) not null default 0,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.sale_items(id bigint generated by default as identity primary key,sale_id bigint not null references public.sales(id) on delete cascade,product_id bigint not null references public.products(id),product_name text not null,sku text,quantity integer not null check(quantity>0),unit_price_usd numeric(12,2) not null,unit_cost_usd numeric(12,2) not null default 0,line_total_usd numeric(12,2) not null);
alter table public.products enable row level security; alter table public.sales enable row level security; alter table public.sale_items enable row level security;
drop policy if exists products_authenticated_all on public.products; create policy products_authenticated_all on public.products for all to authenticated using(true) with check(true);
drop policy if exists sales_select_authenticated on public.sales; create policy sales_select_authenticated on public.sales for select to authenticated using(true);
drop policy if exists sale_items_select_authenticated on public.sale_items; create policy sale_items_select_authenticated on public.sale_items for select to authenticated using(true);
create or replace function public.create_sale(p_customer_name text,p_customer_phone text,p_items jsonb,p_discount_usd numeric,p_payment_currency text,p_paid_amount numeric,p_exchange_rate numeric) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_id bigint; v_invoice text; v_sub numeric(12,2):=0; v_cost numeric(12,2):=0; v_disc numeric(12,2); v_total numeric(12,2); v_paid_usd numeric(12,2); v_change numeric(14,2); it jsonb; pr public.products%rowtype; q integer;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_payment_currency not in('USD','KHR') or p_exchange_rate<=0 or p_paid_amount<0 then raise exception 'Invalid payment'; end if;
 if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Cart is empty'; end if;
 for it in select value from jsonb_array_elements(p_items) loop q:=(it->>'quantity')::integer; if q<=0 then raise exception 'Invalid quantity'; end if; select * into pr from public.products where id=(it->>'product_id')::bigint for update; if not found then raise exception 'Product not found'; end if; if coalesce(pr.quantity,0)<q then raise exception 'Not enough stock for %',pr.name; end if; v_sub:=v_sub+coalesce(pr.price,0)*q; v_cost:=v_cost+coalesce(pr.cost_price,0)*q; end loop;
 v_disc:=greatest(0,least(coalesce(p_discount_usd,0),v_sub)); v_total:=v_sub-v_disc; v_paid_usd:=case when p_payment_currency='USD' then p_paid_amount else p_paid_amount/p_exchange_rate end; if v_paid_usd<v_total then raise exception 'Payment is less than total'; end if; v_change:=case when p_payment_currency='USD' then p_paid_amount-v_total else p_paid_amount-v_total*p_exchange_rate end;
 v_invoice:='KIS-'||to_char(now(),'YYYYMMDD')||'-'||substr(replace(gen_random_uuid()::text,'-',''),1,8);
 insert into public.sales(invoice_no,customer_name,customer_phone,subtotal_usd,discount_usd,total_usd,payment_currency,paid_amount,paid_usd,change_amount,exchange_rate,cost_total_usd,created_by) values(v_invoice,p_customer_name,p_customer_phone,v_sub,v_disc,v_total,p_payment_currency,p_paid_amount,v_paid_usd,greatest(0,v_change),p_exchange_rate,v_cost,auth.uid()) returning id into v_id;
 for it in select value from jsonb_array_elements(p_items) loop q:=(it->>'quantity')::integer; select * into pr from public.products where id=(it->>'product_id')::bigint for update; insert into public.sale_items(sale_id,product_id,product_name,sku,quantity,unit_price_usd,unit_cost_usd,line_total_usd) values(v_id,pr.id,pr.name,pr.sku,q,coalesce(pr.price,0),coalesce(pr.cost_price,0),coalesce(pr.price,0)*q); update public.products set quantity=quantity-q where id=pr.id; end loop;
 return jsonb_build_object('id',v_id,'invoice_no',v_invoice,'subtotal_usd',v_sub,'discount_usd',v_disc,'total_usd',v_total,'payment_currency',p_payment_currency,'paid_amount',p_paid_amount,'change_amount',greatest(0,v_change),'exchange_rate',p_exchange_rate);
end $$;
revoke all on function public.create_sale(text,text,jsonb,numeric,text,numeric,numeric) from public; grant execute on function public.create_sale(text,text,jsonb,numeric,text,numeric,numeric) to authenticated; grant select on public.sales,public.sale_items to authenticated;
